def agent_action(sandbox, agent_body, step_count):
    seat = sandbox.get_swing_seat()
    if seat is None:
        return

    pos = seat.position
    vel = seat.linearVelocity
    vx = vel.x
    vy = vel.y
    target_y = 11.7
    target_x_min = 9.35
    target_x_max = 10.65

    # Pumping phase: apply rightward and vertical forces when on the left side
    if pos.y < target_y:
        if pos.x < 10.0:
            fx = 42.0  # Apply max rightward force
            if vy > 0:
                fy = 42.0  # Apply upward force when moving up
            else:
                fy = -42.0  # Apply downward force when moving down
            sandbox.apply_force_to_seat(fx, fy)
    else:
        # Adjusting phase: try to bring x into the target range
        if pos.x > target_x_max:
            # If x is too far right, apply rightward force when moving left to slow it down
            if vx < 0:
                sandbox.apply_force_to_seat(42.0, 0)
        elif pos.x < target_x_min:
            # If x is too far left, apply rightward force when moving right to slow it down
            if vx > 0:
                sandbox.apply_force_to_seat(42.0, 0)
        else:
            # Already in target x range, no action
            pass
